import React, { useCallback, useEffect } from "react";
import { useTranslation } from "react-i18next";
import { buildField, throwError } from "@/core/helpers";
import InputField from "@/core/components/primitives/input-field/input-field";
import StyledRadioButtons from "@/core/components/primitives/styled-radio-buttons/styled-radio-buttons";
import styles from "./phone-or-email-fields.module.less";
import { Form, FormField, InputRefType } from "@/core/helpers/form-builder";
import { createRef } from "react";
import { LabelKey, Translation } from "@/core/labels/i18n";

export type MethodType = "phone" | "email";

export type ContactFieldType = Omit<FormField, "label" | "errorText" | "isValid"> & {
  /** Type of field (phone or email), used for setting input settings and default values */
  fieldType: MethodType;
  /** Name of the field, has to be unique */
  name: string;
  /** Input field label
   * @defaultValue `phone` or `email`  based on fieldType */
  label?: LabelKey;
  /** Input field placeholder
   * @defaultValue `phone` or `email`  based on fieldType */
  placeholder?: LabelKey;
  /** Current value of the input field, if any */
  value?: string;
  t: Translation;
};

/** Function to create contact input field for PhoneOrEmailFields with fixed values.
 * - `isRequired`:`true` (will then be conditionally enforced in the component so that only current method field is required,
 *    for correct form validation)
 * - `validationType`: `PHONE` or `EMAIL` based on fieldType
 * - `autoComplete`: `tel` or `email` based on fieldType
 * - `inputMode`: `tel` or `email` based on fieldType
 * - `errorText`: label `inputValidationPhone` or `inputValidationEmail` based on fieldType
 */
export const createContactField = ({
  fieldType,
  name,
  label = fieldType === "phone" ? "phone" : "email",
  placeholder,
  value,
  t,
}: ContactFieldType) => {
  return {
    name,
    field: buildField(name, {
      label: t(label),
      placeholder: placeholder && t(placeholder),
      inputMode: fieldType === "phone" ? "tel" : "email",
      validationType: fieldType === "phone" ? "PHONE" : "EMAIL",
      autoComplete: fieldType === "phone" ? "tel" : "email",
      isRequired: true,
      value,
      errorText: fieldType === "phone" ? t("inputValidationPhone") : t("inputValidationEmail"),
      inputRef: createRef<InputRefType>(),
    }),
  };
};

/** Base props that are always required */
export type PhoneOrEmailFieldsProps = {
  /** Form object that contains the fields for phone and email,
   * in charge of all validation and form functions (exampel focusOn)
   */
  form: Form;
  /**
   * Name for the radio button group
   * MUST be unique if several instances of this component are used in the same form
   * This ensures radio button events don't interfere between different instances
   */
  radioGroupName: string;
  /**
   * Label for the radio buttons
   * This describes the entire phone/email selection and input section.
   */
  radioGroupLabel: LabelKey;
  /** Label for radio button for phone number
   * @defaultValue `phone`
   */
  radioLabelPhone?: LabelKey;
  /** Label for radio button for email address
   * @defaultValue `email`
   */
  radioLabelEmail?: LabelKey;
  /** Current method - "phone" or "email" (use `phone` as default start value) */
  method: MethodType;
  /** Name of the phone number field in the form, has to be unique if several instances are used */
  phoneFieldName: string;
  /** Name of the email field in the form, has to be unique if several instances are used */
  emailFieldName: string;
  /** Whether to reverse the order of the radio buttons, with email shown before phone. This does not change the actual method values, just the order they are shown in. */
  reverseOptions?: boolean;
  /** Callback for method type change (radio buttons), in addition to changing which input field is shown and should be required */
  onMethodChange?: (name: string, value: MethodType) => void;
  /** Callback for contact input change (phone number/email address), in addition to basic validation (phone/email) */
  onContactChange: (name: string, value: string) => void;
  /** Optional keydown event handler for the contact input field, useful for example to handle Enter key press */
  onKeyDown?: (event: React.KeyboardEvent<HTMLInputElement>) => void;
};

/**
 * Component that combines radio buttons for selecting phone/email
 * with an InputField that switches between phone and email validation.
 * Only the current field (phone or email based on method) is required so that non current field is not validated.
 */
const PhoneOrEmailFields = ({
  form,
  radioGroupName,
  radioGroupLabel,
  radioLabelPhone = "phone",
  radioLabelEmail = "email",
  method,
  phoneFieldName,
  emailFieldName,
  reverseOptions,
  onMethodChange,
  onContactChange,
  onKeyDown,
}: PhoneOrEmailFieldsProps) => {
  const { t } = useTranslation();

  /** Set which field should be required and the validation type
   * Set validationType to undefined for the non-required field,
   *  so that it is not validated and might cause form to be invalid
   */
  const setValidationSettings = useCallback(
    (method: MethodType) => {
      const phoneField = form.fields.get(phoneFieldName);
      const emailField = form.fields.get(emailFieldName);

      if (phoneField && emailField) {
        const useMethodPhone = method === "phone";

        phoneField.isRequired = useMethodPhone;
        phoneField.validationType = useMethodPhone ? "PHONE" : undefined;

        emailField.isRequired = !useMethodPhone;
        emailField.validationType = !useMethodPhone ? "EMAIL" : undefined;
      }
    },
    [form.fields, phoneFieldName, emailFieldName],
  );

  const handleOnMethodChange = (name: string, value: string) => {
    setValidationSettings(value as MethodType);
    onMethodChange?.(name, value as MethodType);
  };

  const methodInputOptions = [
    {
      label: t(radioLabelPhone),
      value: "phone" as const,
      id: radioGroupName + "_phone",
    },
    {
      label: t(radioLabelEmail),
      value: "email" as const,
      id: radioGroupName + "_email",
    },
  ];

  if (reverseOptions) {
    methodInputOptions.reverse();
  }

  // Get the current active field based on method
  const activeFieldName = method === "phone" ? phoneFieldName : emailFieldName;
  const inputField = form.fields.get(activeFieldName) ?? throwError(`Missing ${method} field: ${activeFieldName}`);

  useEffect(() => {
    setValidationSettings(method);
  }, [method, setValidationSettings]);

  return (
    <div className={styles.wrapper}>
      <StyledRadioButtons
        name={radioGroupName}
        label={t(radioGroupLabel)}
        options={methodInputOptions}
        value={method}
        onChange={(name, value) => handleOnMethodChange(name, value as MethodType)}
      />
      <InputField
        formField={inputField}
        onChange={(name, value) => onContactChange(name, value)}
        onKeyDown={(event) => onKeyDown?.(event)}
        errorText={inputField.errorText}
      />
    </div>
  );
};

export default PhoneOrEmailFields;
